import java.util.*;

public class Main {
    public static void main(String[] args) {
        Library lib = new Library();
        lib.add(new Book("Java", "A"));
        lib.add(new Book("Python", "B"));
        System.out.println(lib.borrow("Java"));
        System.out.println(lib.availableCount());
    }
}

class Book {
    String title;
    String author;
    boolean borrowed;
    Book(String title, String author) {
        this.title = title;
        this.author = author;
    }
}

class Library {
    List<Book> books = new ArrayList<>();
    void add(Book b) {
        books.add(b);
    }
    Book find(String title) {
        for (Book b : books) {
            if (b.title.equals(title)) return b;
        }
        return null;
    }
    String borrow(String title) {
        Book b = find(title);
        if (b == null) return "没有:" + title;
        if (b.borrowed) return "已借出:" + title;
        b.borrowed = true;
        return "借出:" + title;
    }
    void giveBack(String title) {
        Book b = find(title);
        if (b != null) b.borrowed = false;
    }
    int availableCount() {
        int n = 0;
        for (Book b : books) if (!b.borrowed) n++;
        return n;
    }
}

